set-variable.value:
@{
            try {
                var b = context.Request.Body.As<JObject>(preserveContent: true);
                var msgs = b == null ? null : b["messages"] as JArray;
                if (msgs == null) return "";
                var sb = new System.Text.StringBuilder();
                sb.Append(b["model"] == null ? "" : b["model"].ToString()).Append("|");
                foreach (var m in msgs) {
                    string role = (string)m["role"];
                    if (role == "system" || role == "developer") {
                        if (m["content"] == null || m["content"].Type != JTokenType.String) return "";
                        sb.Append(role).Append(":").Append((string)m["content"]).Append("\n");
                    }
                }
                return Convert.ToBase64String(System.Security.Cryptography.SHA256.Create().ComputeHash(System.Text.Encoding.UTF8.GetBytes(sb.ToString())));
            } catch (Exception) { return ""; }
        }

@{
            try {
                if (((string)context.Variables["rp-cache-regulated"]) == "true") return "regulated";
                if (context.Request.Method != "POST") return "unknown-intent";
                var b = context.Request.Body.As<JObject>(preserveContent: true);
                if (b == null) return "unknown-intent";
                if (b["stream"] != null || b["stream_options"] != null) return "streaming";
                if (b["tools"] != null || b["functions"] != null || b["tool_choice"] != null || b["function_call"] != null || b["parallel_tool_calls"] != null) return "tools";
                if (b["response_format"] != null) return "response-format";
                foreach (var p in b.Properties()) {
                    string k = p.Name;
                    if (k == "messages" || k == "model") continue;
                    if (k == "temperature" || k == "top_p" || k == "n") {
                        if ((p.Value.Type == JTokenType.Integer || p.Value.Type == JTokenType.Float) && (double)p.Value == 1.0) continue;
                    }
                    return "model-params";
                }
                var msgs = b["messages"] as JArray;
                if (msgs == null) return "unknown-intent";
                int users = 0;
                string text = "";
                foreach (var m in msgs) {
                    string role = (string)m["role"];
                    var c = m["content"];
                    if (c == null || c.Type != JTokenType.String) return "unknown-intent";
                    if (role == "system" || role == "developer") continue;
                    if (role != "user") return "low-confidence";
                    users++;
                    text = (string)c;
                }
                text = text.Trim();
                if (text.Length == 0) return "blank";
                if (users != 1 || text.Length < 12 || text.Length > 200) return "low-confidence";
                if (System.Text.RegularExpressions.Regex.IsMatch(text, (string)context.Variables["rp-cache-deny-sensitive"])) return "sensitive-intent";
                if (System.Text.RegularExpressions.Regex.IsMatch(text, (string)context.Variables["rp-cache-deny-identifier"])) return "identifier";
                if (System.Text.RegularExpressions.Regex.IsMatch(text, (string)context.Variables["rp-cache-deny-mutation"])) return "mutation";
                if (System.Text.RegularExpressions.Regex.IsMatch(text, (string)context.Variables["rp-cache-deny-analytics"])) return "analytics";
                if (System.Text.RegularExpressions.Regex.IsMatch(text, (string)context.Variables["rp-cache-deny-scope"])) return "scoped-intent";
                if (System.Text.RegularExpressions.Regex.IsMatch(text, (string)context.Variables["rp-cache-deny-dynamic"])) return "dynamic-intent";
                if (!System.Text.RegularExpressions.Regex.IsMatch(text, (string)context.Variables["rp-cache-allow"])) return "unknown-intent";
                if (!System.Text.RegularExpressions.Regex.IsMatch((string)context.Variables["rp-cache-partition"], (string)context.Variables["rp-cache-partition-pattern"])) return "no-partition";
                if (context.Subscription == null || string.IsNullOrEmpty(context.Subscription.Id) || context.Product == null || string.IsNullOrEmpty(context.Product.Id)) return "no-scope";
                if (((string)context.Variables["rp-cache-vary"]).Length == 0) return "low-confidence";
                return "eligible";
            } catch (Exception) { return "unknown-intent"; }
        }
